noncomputable def VTask.memPartition {α : Type u_1} (f : ℕ → Set α) (n : ℕ) : Set (Set α) :=
match n with
| 0 => {univ}
| succ n =>
  let prev_partition := VTask.memPartition f n;
  let rec split_sets (s : Set α) (acc : List (Set α)) : List (Set α) :=
    match s with
    | ∅ => acc
    | insert x xs =>
      let in_f_i := mem_of_mem_of_subset (insert x xs) (f n);
      let out_f_i := mem_of_not_mem_of_subset (insert x xs) (f n).compl;
      split_sets xs ((in_f_i :: out_f_i :: acc))
  let new_partition : Set (Set α) := prev_partition.bind fun s => Set.insertMany (split_sets s [])
  new_partition
